    # If all digits are 9, the next palindrome is 10...01 (length + 1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, middle: str, length: int) -> str:
        if length % 2 == 0:
            return left + left[::-1]
        else:
            return left + middle + left[::-1]

    # Split the number into left, middle and right parts
    if length % 2 == 0:
        left = s[:length // 2]
        middle = ''
        right = s[length // 2:]
    else:
        left = s[:length // 2]
        middle = s[length // 2]
        right = s[length // 2 + 1:]

    # Create palindrome by mirroring left and middle
    palindrome = make_palindrome(left, middle, length)
    if int(palindrome) > num:
        return int(palindrome)

    # Increment the middle part and propagate the carry if needed
    if length % 2 == 0:
        # Even length: increment left as a whole number
        left_num = int(left) + 1
        left = str(left_num).zfill(len(left))
        palindrome = make_palindrome(left, '', length)
