def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all digits are '9', the next palindrome is 10..01 with length+1 digits
    if all(ch == '9' for ch in s):
        return n + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    half = (length + 1) // 2
    left = s[:half]  # left half + middle if odd

    # Form a palindrome by mirroring left to right
    if length % 2 == 0:
        palindrome = left + left[::-1]
    else:
        palindrome = left + left[-2::-1]

    palindrome_num = int(palindrome)

    if palindrome_num > n:
        return palindrome_num

    # Increment the left half and form palindrome again
    # Convert left to int, increment, convert back to string with leading zeros if needed
    incremented_left = str(int(left) + 1)
    # If increment caused length to increase, adjust palindrome length accordingly
    if len(incremented_left) > len(left):
        # This means something like 999 + 1 -> 1000, palindrome length increases by 1
        if length % 2 == 0:
            # even length palindrome, now length increases by 1
            palindrome = incremented_left + incremented_left[:-1][::-1]
        else:
            palindrome = incremented_left + incremented_left[:-2][::-1]
    else:
        if length % 2 == 0:
            palindrome = incremented_left + incremented_left[::-1]
        else:
            palindrome = incremented_left + incremented_left[-2::-1]

    return int(palindrome)

