    # Since bg can be positive or negative, choose k accordingly

    # If bg > 0, minimal x occurs at k = k_min
    # If bg < 0, minimal x occurs at k = k_max

    if bg > 0:
        k = k_min
    else:
        k = k_max

    x = x0 + k * bg
    y = y0 - k * ag

    if x < 0 or y < 0:
