def get_total_number_of_sequences(m: int, n: int) -> int:
    if n == 0:
        return 0
    # dp[i][x]: number of valid sequences of length i ending with x
    # i ranges from 1 to n
    # x ranges from 1 to m
    dp = [ [0] * (m + 1) for _ in range(n + 1) ]

    # Base case: sequences of length 1, any element from 1 to m
    for x in range(1, m + 1):
