from collections.abc import Mapping, Sequence

def remove_column(data, key_or_index):
    if isinstance(data, Mapping):
        # Remove dictionary entries where key matches key_or_index
        return {k: remove_column(v, key_or_index) for k, v in data.items() if k != key_or_index}
    elif isinstance(data, Sequence) and not isinstance(data, (str, bytes)):
        # If key_or_index is int, remove element at that index from each sublist if possible
        # Recursively process each element
        if isinstance(key_or_index, int):
            # For a list of lists: remove element at key_or_index from each sublist
            new_list = []
            for item in data:
                if (
                    isinstance(item, Sequence) and not isinstance(item, (str, bytes))
                    and 0 <= key_or_index < len(item)
                ):
                    # remove element at index key_or_index
                    # process remaining elements recursively
                    new_sublist = [remove_column(subitem, key_or_index) for i, subitem in enumerate(item) if i != key_or_index]
                    new_list.append(new_sublist)
                else:
                    new_list.append(remove_column(item, key_or_index))
            return new_list
        else:
            # key_or_index is not int: just recursively process elements
            return [remove_column(item, key_or_index) for item in data]
