def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # Helper to check if all digits are '9'
    if all(ch == '9' for ch in s):
        # Next palindrome will be 10...01 (length+1 digits)
        return n + 2  # e.g. 9 -> 11, 99 -> 101, 999 -> 1001

    def make_palindrome(left, middle, odd_length):
        if odd_length:
            return int(left + middle + left[::-1])
        else:
            return int(left + left[::-1])

    def increment_str_num(num_str):
        # Increment numeric string by 1 and return as string
        num = int(num_str)
        return str(num + 1)

    odd_length = (length % 2 != 0)
    if odd_length:
        left = s[:length//2]
        middle = s[length//2]
        right = s[length//2+1:]
    else:
        left = s[:length//2]
        middle = ''
        right = s[length//2:]

    # Form palindrome by mirroring left to right
    pal_candidate = make_palindrome(left, middle, odd_length)

    if pal_candidate > n:
        return pal_candidate

    # Need to increment the middle part and form palindrome again
    if odd_length:
        # Increment middle digit + left part as a single number
        left_middle_num = left + middle
        incremented = str(int(left_middle_num) + 1)
        if len(incremented) > len(left_middle_num):
            # overflow, e.g. 999 -> 1000
            # palindrome will be one digit longer
            # which means left grows by 1 digit and middle resets to ''
            new_left = incremented[:-1]
            new_middle = incremented[-1]
        else:
            new_left = incremented[:-1]
            new_middle = incremented[-1]
        return make_palindrome(new_left, new_middle, True)
    else:
        # Even length: increment left half as number and mirror
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            # overflow, length increases by 1
            # e.g. 99 -> 100 palindrome is 101
            # so palindrome length increases by 1
            # so new palindrome is 1 + zeros + 1 of length length+1
            return int('1' + ('0' * (length - 1)) + '1')
