def monotonic(l):
    if isinstance(l, list):
        # For lists:
        # Return True if list is monotonic (non-decreasing or non-increasing), allowing duplicates.
        # Return False otherwise.
        # No loops or sorting methods allowed.
        def non_decreasing(seq):
            if len(seq) < 2:
                return True
            return seq[0] <= seq[1] and non_decreasing(seq[1:])
        def non_increasing(seq):
            if len(seq) < 2:
                return True
            return seq[0] >= seq[1] and non_increasing(seq[1:])
        return non_decreasing(l) or non_increasing(l)
    elif isinstance(l, str):
        # For strings:
        # Return False if duplicates exist
        # Otherwise, return (True, original string) if strictly monotonic increasing or decreasing (alphabetical or reverse alphabetical)
        # Return False otherwise
        def has_duplicates(s):
            if len(s) < 2:
                return False
            return s[0] in s[1:] or has_duplicates(s[1:])
        def strictly_increasing(s):
            if len(s) < 2:
                return True
            return s[0] < s[1] and strictly_increasing(s[1:])
        def strictly_decreasing(s):
            if len(s) < 2:
                return True
            return s[0] > s[1] and strictly_decreasing(s[1:])
        if has_duplicates(l):
            return False
        if strictly_increasing(l) or strictly_decreasing(l):
            return True, l
        return False
