import collections
import heapq
import bisect
from typing import *
from collections import *

def order_by_points(nums):
    def key_func(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n >= 0:
            return sum(digits)
        else:
            # Negate only the first digit's value before summing
            return -digits[0] + sum(digits[1:])
    return sorted(nums, key=key_func)
